// Source-derived helpers required by ClumpStage2/Assembly2/SleepStage2.
// Bodies from openrbx Guid.cpp, Primitive.cpp, MotorJoint.cpp and Link.cpp.
#include "util/Guid.h"
#include "v8world/Primitive.h"
